from pathlib import Path
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parent.parent
url=(root/'index.html').as_uri()+'?daily=20261101&notut=1'
out=root/'tests/screenshots/stage-current'
with sync_playwright() as p:
 b=p.chromium.launch();pg=b.new_page(viewport={'width':390,'height':844});errors=[];pg.on('pageerror',lambda e:errors.append(str(e)))
 pg.goto(url);pg.wait_for_timeout(1300)
 pg.click('#btnSettings');assert pg.locator('#tglMusic').get_attribute('aria-pressed')=='true';pg.click('#tglMusic');assert pg.locator('#tglMusic').get_attribute('aria-pressed')=='false';pg.click('#tglMusic');pg.locator('#nicknameInput').fill('person@example.com');pg.click('#btnNickname');assert 'پذیرفته نشد' in pg.locator('#nicknameMessage').inner_text();pg.locator('#nicknameInput').fill('ابرک');pg.click('#btnNickname');assert 'ذخیره شد' in pg.locator('#nicknameMessage').inner_text();pg.screenshot(path=str(out/'390x844-nickname.png'));pg.click('#btnSetBack');
 pg.click('#btnCampaign');assert pg.locator('#campaignChoices button').count()==5;assert pg.locator('#campaignChoices button').nth(1).is_disabled();pg.screenshot(path=str(out/'390x844-campaign.png'));pg.locator('#campaignChoices button').first.click();assert pg.evaluate("window.__game.state.mode==='campaign'");pg.evaluate("window.__game.state.t=44.99;window.__game.state.nextArrival=999;window.__game.state.sla=100");pg.wait_for_selector('#ovOver.show');assert 'کامل شد' in pg.locator('#overTitle').inner_text();pg.click('#btnOverMenu');pg.click('#btnCampaign');assert not pg.locator('#campaignChoices button').nth(1).is_disabled();pg.click('#btnCampaignBack');
 pg.click('#btnDaily');assert 'رفت‌وآمد سریع' in pg.locator('#dailyIntro').inner_text();pg.screenshot(path=str(out/'390x844-daily-intro.png'))
 pg.click('#btnDailyStart');pg.wait_for_timeout(100);assert pg.evaluate("window.__game.state.mode==='daily'&&window.__game.state.modifier.id==='rush'")
 pg.evaluate('window.__game.state.t=44.99;window.__game.state.nextArrival=999');pg.wait_for_selector('#ovUpgrade.show');assert pg.locator('#upgradeChoices button').count()==3;pg.screenshot(path=str(out/'390x844-upgrade.png'));pg.locator('#upgradeChoices button').first.click();assert pg.evaluate('window.__game.state.upgrades.length===1');pg.evaluate('window.__game.state.sla=0');pg.wait_for_selector('#ovSecondChance.show');pg.screenshot(path=str(out/'390x844-second-chance.png'));pg.click('#btnSecondChance');assert pg.evaluate('window.__game.state.secondChanceUsed&&!window.__game.state.over');pg.evaluate('window.__game.state.sla=0');pg.wait_for_selector('#ovOver.show');assert pg.evaluate("window.__game.DB.dailyStreak.count===1 && window.__game.DB.daily['20261101'].runs===1");pg.click('#btnOverMenu');pg.click('#btnDaily');assert 'آخرین رشته' in pg.locator('#dailyMissionsIntro').inner_text();assert not errors,errors
 print('PASS daily intro/board/offline start and once-only second-chance UI');b.close()
